import React from 'react';

const Hero = () => {
    return (
        <section id="inicio" className="hero">
            <div className="hero-content">
                <h1>Recordar para Defender la Democracia</h1>
                <p className="subtitle">Campaña educativa sobre la dictadura de los hermanos Tinoco en Costa Rica</p>
                <p className="description">
                    Este proyecto tiene como propósito difundir de manera clara, accesible e innovadora 
                    la relevancia histórica de la dictadura de los hermanos Tinoco y su impacto en la 
                    construcción de la democracia nacional.
                </p>
                <a href="#contexto" className="btn-primary">Conocer más</a>
            </div>
        </section>
    );
};

export default Hero;
